import { useEffect, useState } from 'react';

// The page's own title, before the Watchlist changes it.
document.title = 'Playground';

const INITIAL = [
  { id: 'a1', title: 'Arrival', watched: true },
  { id: 'p2', title: 'Past Lives', watched: false },
  { id: 'd3', title: 'Dune: Part Two', watched: false },
];

function Watchlist() {
  const [movies, setMovies] = useState(INITIAL);
  const left = movies.filter((m) => !m.watched).length;

  useEffect(() => {
    const previous = document.title;
    document.title = `${left} to watch · Watchlist`;
    return () => {
      document.title = previous;
    };
  }, [left]);

  function toggle(id) {
    setMovies(movies.map((m) => (m.id === id ? { ...m, watched: !m.watched } : m)));
  }

  return (
    <section>
      <p id="left">{left} to watch</p>
      <ul>
        {movies.map((m) => (
          <li key={m.id}>
            {m.title}
            <button onClick={() => toggle(m.id)}>{m.watched ? 'Watched' : 'Mark watched'}</button>
          </li>
        ))}
      </ul>
    </section>
  );
}

export default function App() {
  const [show, setShow] = useState(true);
  return (
    <main>
      <button id="hide" onClick={() => setShow(false)}>Hide watchlist</button>
      {show && <Watchlist />}
    </main>
  );
}
